"""Generate a portable static site. Python standard library only."""
from pathlib import Path
from html import escape as e
import json, shutil, re

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
MENU=json.loads((ROOT/'data/menu.json').read_text())
ORDER='https://order.toasttab.com/online/con-azucar-cafe-630-k-street-suite-100'
MAP='https://www.google.com/maps/search/?api=1&query=630+K+St+%23100+Sacramento+CA+95814'
GALLERY_ALTS=['Two guests holding canned coffee at an outdoor event','A Café X guest holding a giant concha','A group sharing pieces of a Concha Gigante','Friends raising coffee and matcha cans together','Guests breaking into a giant concha at a celebration','A guest holding a tray of Café X drinks','A guest showing a can of Café X coffee','Two friends sharing drinks and a giant concha','A Café X team member with coffee and mini conchas','Sharing pan dulce at a Café X gathering','Cans of Café X coffee and matcha on a table','Friends celebrating with a Concha Gigante','Two Café X team members holding bags of mini conchas','Friends enjoying freshly baked concha together']
GALLERY=[('event-portrait.webp','Café X canned drinks raised together'),('event-wide.webp','Sharing a Concha Gigante at a community event'),('event-coffee.webp','Friends enjoying Café X drinks at an event')]+[(f'gallery-{i+1}.webp',alt) for i,alt in enumerate(GALLERY_ALTS)]
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir()
shutil.copytree(ROOT/'assets',OUT/'assets')
for file in ['styles.css','app.js']:shutil.copy(ROOT/file,OUT/file)
shutil.copytree(ROOT/'data',OUT/'data')

def image(file,alt,cls='',eager=False):
    return f'<img class="{cls}" src="{{BASE}}assets/images/{file}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async" '+('fetchpriority="high" ' if eager else '')+'width="1100" height="1100">'
def link(text,path,cls='button',external=False):
    return f'<a class="{cls}" href="{path if external else "{BASE}"+path}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{text}<span aria-hidden="true">{ARROW}</span></a>'
ARROW='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14M12 5l7 7-7 7" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'
def head(title,active):
    nav=''.join(f'<a href="{{BASE}}{path}/"'+(' aria-current="page"' if active==path else '')+f'>{label}</a>' for path,label in [('menu','Menu'),('ourstory','Our Story'),('gallery','Gallery'),('shop','Shop'),('contact-10','Contact')])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | CAFÉX</title><meta name="description" content="Coffee from Nayarit, fresh jugos, and pan dulce worth sharing. Your next cafecito is waiting at Café X, 630 K Street, Sacramento."><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#fff3dc"><meta property="og:title" content="Café X · Un cafecito y algo más"><meta property="og:description" content="Mexican coffee, pan dulce, and fresh jugos on K Street."><meta property="og:type" content="website"><link rel="icon" href="{{BASE}}assets/images/logo.png"><link rel="preload" as="font" href="{{BASE}}assets/fonts/fraunces.ttf" type="font/ttf" crossorigin><link rel="stylesheet" href="{{BASE}}styles.css"><script src="{{BASE}}app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="announcement"><span>Cafecito, pan dulce y buena compañía.</span><a href="{{BASE}}contact-10/">630 K Street, Sacramento {ARROW}</a></div><header class="site-header"><a class="brand" href="{{BASE}}" aria-label="Café X home"><img src="{{BASE}}assets/images/logo.png" alt="CAFÉX Coffee & Juice Bar" width="96" height="86"></a><nav id="navigation" aria-label="Main navigation">{nav}</nav><div class="header-actions">{link('Order Online',ORDER,'button small',True)}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Explore <span aria-hidden="true">+</span></button></div></header><main id="main">'''
def footer():
    return f'''</main><footer><div class="footer-top"><div class="footer-brand"><a href="{{BASE}}"><img src="{{BASE}}assets/images/logo.png" alt="Café X home" width="120" height="110"></a><p>Coffee & juice bar.<br>Hecho con energía mexicana.</p></div><div><h2>Come on over.</h2><a href="{MAP}" target="_blank" rel="noopener noreferrer">630 K St #100<br>Sacramento, CA 95814</a><a href="tel:+19169961306">916-996-1306</a></div><div><h2>Make it a daily thing.</h2><p>Monday - Friday <span>7am - 6pm</span><br>Saturday - Sunday <span>7am - 8pm</span></p><a href="mailto:info@hechoencafex.com">info@hechoencafex.com</a></div><div><h2>Around here.</h2><a href="https://www.instagram.com/hechoencafex/" target="_blank" rel="noopener noreferrer">Instagram {ARROW}</a><a href="https://www.tiktok.com/@hechoencafex" target="_blank" rel="noopener noreferrer">TikTok {ARROW}</a><a href="https://www.facebook.com/profile.php?id=61587903140849" target="_blank" rel="noopener noreferrer">Facebook {ARROW}</a></div></div><p class="footer-word" aria-hidden="true">Hasta pronto.</p><div class="footer-bottom"><span>© 2026 CAFÉX</span><a href="{{BASE}}menu/">Coffee is always a good idea.</a><span>Demo website</span></div></footer><dialog id="photo-dialog" aria-label="Photo viewer"><button class="dialog-close" aria-label="Close photo viewer">Close ×</button><button class="photo-prev" aria-label="Previous photo">←</button><figure><img id="dialog-image" alt=""><figcaption id="photo-caption"></figcaption></figure><button class="photo-next" aria-label="Next photo">→</button></dialog></body></html>'''
def intro(kicker,title,description):
    return f'<section class="page-intro"><h1>{title}</h1><p class="intro-copy">{description}</p></section>'
def visit():
    return f'''<section class="visit section-pad"><div><h2>¿Nos vemos<br><em>en el café?</em></h2><p>We saved you a spot on K Street.</p></div><div class="visit-ticket"><h3>Come for a cafecito.</h3><address>630 K St #100<br>Sacramento, CA 95814</address><p>Mon - Fri · 7am - 6pm<br>Sat - Sun · 7am - 8pm</p>{link('Find us',MAP,'button',True)}</div></section>'''
def home():
    items=[('horchata-latte.webp','Horchata Latte','Cinnamon, espresso, happiness.','Cafecitos','coffee'),('concha-gigante.webp','Concha Gigante','A little extra? Always.','Pan Dulce','bakery'),('nopal-power.webp','Nopal Power','The mercado, freshly squeezed.','Jugos','juice'),('vampiro.webp','Vampiro','Turn up the fruit.','Energy','energy')]
    sampler=''.join(f'<a class="sampler-item {color}" href="{{BASE}}menu/?category={category}"><div class="sampler-title"><h3>{title}</h3>{ARROW}</div><figure>{image(file,alt)}</figure><p>{copy}</p></a>' for file,alt,copy,title,category in items for color in [category])
    return f'''<section class="hero"><figure class="hero-media">{image('hero.webp','Mexican coffee, café de olla in a clay mug, and a pink concha with a nopal cactus','',True)}</figure><div class="hero-content"><h1>Un cafecito.<br><em>Y algo más.</em></h1><div class="hero-invitation"><p>Mexican coffee. Fresh jugos.<br>Pan dulce worth sharing.</p>{link('Find your favorito','menu/','button yellow')}</div></div><span class="hero-seal"><span>HECHO CON</span><strong>energía<br>mexicana</strong><span>CAFÉ X · SACRAMENTO</span></span><a class="hero-caption" href="{{BASE}}ourstory/">Coffee from Nayarit. A welcome for everyone. {ARROW}</a></section>
<section class="welcome section-pad"><h2>Pull up a chair.<br><em>There’s a lot to love.</em></h2><div><p>A cafecito that tastes like home. A concha that barely fits on the table. Something fresh, something sweet, and someone to share it with.</p><p>Welcome to Café X, your Mexican coffee & juice bar in downtown Sacramento.</p></div></section>
<section class="sampler" aria-label="Explore the menu">{sampler}</section><div class="menu-link-bar"><p>From the first sip to the last migaja.</p>{link('See the whole menu','menu/','text-link')}</div>
<section class="concha-feature"><div class="concha-copy"><h2>Big concha.<br><em>Bigger plans.</em></h2><p>Meet the Concha Gigante. Tear it, share it, make a little mess. Some things are just too good to enjoy alone.</p>{link('Meet the pan dulce','menu/?category=bakery','button')}</div><figure>{image('event-wide.webp','A Café X guest proudly holding a Concha Gigante at an outdoor gathering')}<figcaption>Yes, it really is that big.</figcaption></figure><span class="concha-note" aria-hidden="true">Para<br>compartir</span></section>
<section class="origin section-pad"><div class="origin-title"><h2>Mucho México.<br><em>In every cup.</em></h2><p>Our founder’s story begins in Zacatecas. Our coffee’s begins in Nayarit. Both come together here, with the flavors and hospitality we grew up with.</p>{link('The story behind your cup','ourstory/','text-link')}</div><figure class="origin-photo">{image('caf-de-olla.webp','Café de olla in a traditional decorated clay cup')}<figcaption>Café de olla · Cinnamon. Piloncillo. Tradition.</figcaption></figure><div class="origin-note"><span>Nayarit<br>México</span><p>Where our coffee<br>gets its start.</p></div></section>
<section class="community"><div class="community-heading"><h2>Made for<br><em>the juntada.</em></h2><div><p>Good coffee has a way of bringing people together. Here’s a little of our world.</p>{link('Meet our people','gallery/','text-link')}</div></div><div class="photo-wall"><a href="{{BASE}}gallery/">{image('gallery-9.webp','Café X team member with coffee and bags of mini conchas')}</a><a href="{{BASE}}gallery/">{image('event-portrait.webp','Friends raising Café X coffee and matcha cans together')}</a><a href="{{BASE}}gallery/">{image('gallery-8.webp','Two friends sharing drinks and a Concha Gigante')}</a></div><div class="catering-bar"><p>Bring a little Café X to your next celebration.</p>{link('Let’s talk catering','contact-10/?subject=Catering','button outline')}</div></section>
<section class="to-go section-pad"><figure>{image('canned.webp','Three Café X canned drinks overlooking a Sacramento soccer field')}</figure><div><h2>Buen café.<br><em>Wherever.</em></h2><p>Your coffee, matcha, jugos, and energy favorites, freshly made and sealed to go. Grab one for the road, or a four-pack or six-pack for your people.</p>{link('Order something good',ORDER,'button',True)}</div></section>{visit()}'''
def story():
    return intro('Our Story','A little México.<br><em>A lot of corazón.</em>','Our story is in the places we come from, the coffee we pour, and the people around our table.')+f'''<section class="story-opening section-pad"><figure>{image('event-coffee.webp','Friends enjoying Café X canned drinks at a gathering','',True)}</figure><div><h2>It begins<br><em>in Zacatecas.</em></h2><p>Our founder’s Mexican heritage is at the heart of Café X. The flavors, the generosity, the simple pleasure of gathering over something good: we bring it all to our coffee & juice bar on K Street.</p><p>The nopal in our logo stands for resilience and growth. It’s a reminder of where we come from, and what we’re growing together.</p></div></section><section class="story-statement section-pad"><h2>De nuestra tierra,<br><em>para tu taza.</em></h2><p>From our land, to your cup.</p></section><section class="story-grid section-pad">'''+''.join(f'<article>{image(im,alt)}<div><h2>{title}</h2><p>{copy}</p></div></article>' for im,alt,title,copy in [
      ('coffee.webp','Freshly poured coffee','The coffee: Nayarit.','Our coffee comes from Nayarit, México. Roasted dark for a rich, full-bodied cup, it connects our daily ritual to the people and land behind it.'),
      ('juice.webp','Freshly poured red juice','A taste of the mercado.','Whole fruits and vegetables, pressed into vibrant jugos. Inspired by Mexican juice stands and made with locally sourced produce.'),
      ('pan-dulce.webp','Café X Concha Gigante','There’s always room for pan dulce.','Mini conchitas, a Concha Gigante, and all the sweet things in between. Our daily baked favorites belong next to your cafecito.'),
      ('vampiro.webp','Café X Vampiro energy drink','Un poquito más de energía.','Our Red Bull partnership brings fruit-forward energy infusions to the menu. Pick your favorite, and take a little extra energy with you.'),
      ('canned.webp','A selection of canned Café X drinks','Take the good stuff along.','Coffee, matcha, jugos, and energy infusions sealed fresh in cans. One for you, or four-packs and six-packs to share.')])+f'</section>{visit()}'
def menu_page():
    categories=''.join(f'<button data-category="{e(s["name"])}" aria-pressed="false">{e(s["name"])}</button>' for s in MENU)
    body=intro('The Menu','¿Qué se te antoja?' ,'Cafecitos, pan dulce, fresh jugos, and a little something for every mood.')+f'''<section class="menu-section section-pad"><div class="menu-tools"><label class="search-label"><span>Find your favorite</span><input id="menu-search" type="search" placeholder="Try horchata, concha, matcha…" autocomplete="off"></label>{link('Order Online',ORDER,'button',True)}</div><div class="category-filters" role="group" aria-label="Filter menu by category"><button class="active" data-category="all" aria-pressed="true">All</button>{categories}</div><p class="menu-note">Menu and prices from Café X. Final availability and pricing are confirmed when ordering.</p><p class="results-message sr-only" aria-live="polite"></p><div class="no-results" hidden><h2>No matches this time.</h2><p>Try another flavor or browse the full menu.</p><button class="button reset-filters">Show all items</button></div>'''
    for section in MENU:
        body+=f'<section class="menu-category" data-menu-category="{e(section["name"])}"><h2>{e(section["name"]).replace("/", "/<wbr>")}</h2><p class="category-description">{e(section.get("description",""))}</p><div class="menu-grid">'
        for item in section['items']:
            name=item['name'].rstrip('*'); desc=item.get('description',''); img=image(item['image'].replace('.webp','-thumb.webp'),name) if 'image' in item else '<div class="menu-monogram" aria-hidden="true">CAFÉX</div>'
            body+=f'<article class="menu-item" data-search="{e((name+" "+desc).lower())}">{img}<div><div class="menu-item-title"><h3>{e(name)}</h3><span>{e(item.get("price",""))}</span></div><p>{e(desc)}</p></div></article>'
        body+='</div></section>'
    return body+'</section>'
def gallery():
    return intro('Gallery','La vida<br><em>en Café X.</em>','Coffee brings us together. Take a look at the pop-ups, celebrations, and people that make Café X.')+f'<div class="gallery-action section-pad">{link("Book Catering","contact-10/?subject=Catering","button")}</div><section class="gallery-grid section-pad">'+''.join(f'<button class="gallery-photo" data-photo="{i}" aria-label="Open photo {i+1}: {e(alt)}">{image(file,alt,eager=i<3)}<span aria-hidden="true">↗</span></button>' for i,(file,alt) in enumerate(GALLERY))+'</section>'+visit()
def contact():
    return intro('Contact','Hola.<br><em>We’re all ears.</em>','A question, a celebration, or just a hello. We’d love to hear from you.')+f'''<section class="contact-grid section-pad"><div class="contact-details"><h2>Let’s make something happen.</h2><a href="tel:+19169961306">916-996-1306 ↗</a><a href="mailto:info@hechoencafex.com">info@hechoencafex.com ↗</a><p>Planning an event? Tell us a little about it and we’ll help you bring the energía.</p>{image('event-portrait.webp','A gathering with Café X canned drinks')}</div><form id="contact-form"><div class="field-row"><label>First Name<input name="first-name" required autocomplete="given-name" maxlength="80"></label><label>Last Name<input name="last-name" required autocomplete="family-name" maxlength="80"></label></div><label>Email<input type="email" name="email" required autocomplete="email" maxlength="150"></label><label>Message<textarea name="message" rows="6" required maxlength="3000"></textarea></label><p class="form-note">This demo prepares your message in your email app. You can review it before sending.</p><button class="button" type="submit">Prepare Email <span aria-hidden="true">↗</span></button><p id="contact-status" role="status"></p></form></section><section class="location section-pad reveal"><h2>See you<br><em>on K Street.</em></h2><div><address>630 K St #100<br>Sacramento, CA 95814</address><dl><div><dt>Monday - Friday</dt><dd>7am - 6pm</dd></div><div><dt>Saturday - Sunday</dt><dd>7am - 8pm</dd></div></dl>{link('Get Directions',MAP,'button',True)}</div></section>'''
def shop():
    return f'''<section class="shop-hero section-pad"><div><h1>Something good<br><em>is on its way.</em></h1><p class="intro-copy">Our online shop is coming soon. Be the first to hear what’s next.</p><form id="notify-form"><label for="notify-email">Email address</label><div class="notify-row"><input id="notify-email" name="email" type="email" required placeholder="you@example.com" autocomplete="email"><button class="button" type="submit">Notify Me ↗</button></div><p class="form-note">Opens an email request to Café X. You’ll review and send it from your email app.</p><p role="status" id="notify-status"></p></form><a class="text-link" href="{ORDER}" target="_blank" rel="noopener noreferrer">Order your café favorites now ↗</a></div><figure>{image('canned.webp','Fresh Café X canned coffee and juice','',True)}</figure></section>'''
pages=[('', 'Un cafecito y algo más',home),('ourstory','Our Story',story),('menu','Menu',menu_page),('gallery','Gallery',gallery),('contact-10','Contact',contact),('shop','Shop',shop),('category/all-products','Shop',shop)]
for route,title,fn in pages:
    folder=OUT/route;folder.mkdir(parents=True,exist_ok=True)
    base='../'*len(route.split('/')) if route else './'
    (folder/'index.html').write_text((head(title,route)+fn()+footer()).replace('{BASE}',base))
(OUT/'404.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Page not found | CAFÉX</title><style>body{margin:0;background:#fff3dc;color:#94362a;font-family:Arial,sans-serif;min-height:100dvh;display:grid;place-items:center}main{padding:32px;max-width:750px}p{line-height:1.6;color:#673b2d}h1{font-size:clamp(48px,9vw,100px);line-height:.95;letter-spacing:-.05em;margin:30px 0}a{display:inline-block;margin-top:25px;background:#94362a;color:#fff3dc;padding:18px 24px;text-decoration:none}a:focus-visible{outline:3px solid #f2f3e7;outline-offset:5px}</style></head><body><main><p>CAFÉX / 404</p><h1>LOST YOUR<br>CAFECITO?</h1><p>This page isn’t on the menu. Let’s get you back to something good.</p><a id="return-home" href="/">Back to Home ↗</a></main><script>if(location.hostname.endsWith('.github.io'))document.getElementById('return-home').href='/DEMO-CAFE-X/';</script></body></html>''')
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(OUT/'.nojekyll').touch()
# Support GitHub Pages' default main/(root) publishing as well as dist uploads.
# Shared styles, scripts, fonts, images, and data already live at the root.
for generated in [*OUT.rglob('*.html'), OUT/'robots.txt', OUT/'.nojekyll']:
    destination=ROOT/generated.relative_to(OUT)
    destination.parent.mkdir(parents=True,exist_ok=True)
    shutil.copy2(generated,destination)
print(f'Built {len(pages)} pages + 404 in dist and the repository root')
